    if (!box.querySelector(".ie-hint")) box.insertAdjacentHTML("afterbegin", `<p class="ie-hint">✏️ Tap anything to edit it.</p>`);
    const tEl = box.querySelector(".nu-title"); if (tEl && !tEl.textContent.trim()) { tEl.classList.add("ie-empty"); tEl.textContent = "Add a title"; }
    editable(tEl, { id, field: "title", required: true, get: () => e.dinnerTheme || e.title, toPatch: (v) => { e.title = v; return e.dinnerTheme ? { dinnerTheme: v } : { pubTitle: v }; } });
    const spans = [...box.querySelectorAll(".nu-meta span")];
    const dateSpan = spans[0]; if (dateSpan) { const d0 = document.createElement("span"); const t0 = document.createElement("span"); d0.textContent = e.date ? new Date(e.date + "T12:00:00").toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" }) : "Pick a date"; t0.textContent = e.startTime ? new Date("2000-01-01T" + e.startTime).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" }).replace(/:00(?=\s)/, "").replace(/\s([AP]M)$/, (_, x) => x.toLowerCase()) : "Add a time"; dateSpan.replaceWith(d0); d0.after(t0);
      editable(d0, { id, field: "date", kind: "date", get: () => e.date, toPatch: (v) => { e.date = v; return { date: v }; }, show: (v) => new Date(v + "T12:00:00").toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" }) });
      editable(t0, { id, field: "time", kind: "time", get: () => e.startTime, toPatch: (v) => { e.startTime = v; return { startTime: v }; }, show: (v) => new Date("2000-01-01T" + v).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" }).replace(/:00(?=\s)/, "").replace(/\s([AP]M)$/, (_, x) => x.toLowerCase()) }); }
